    }

    int dequeue() {
        if (data.isEmpty()) return -1;
        int x = data.get(0);                     // the front is always index 0
        for (int i = 0; i + 1 < data.size(); i++) {
            data.set(i, data.get(i + 1));        // shift everything one place left: O(n)
        }
        data.remove(data.size() - 1);
        return x;
    }

    int front() {
        return data.isEmpty() ? -1 : data.get(0);
    }

    boolean isEmpty() {
        return data.isEmpty();
    }

