class ArrayQueue {
  constructor() {
    this.data = [];
    this.head = 0;                       // index of the front item
  }
  enqueue(x) {
    this.data.push(x);
  }
  dequeue() {
    if (this.head === this.data.length) return -1;   // empty
    const x = this.data[this.head];
    this.head++;                         // the front moves right: O(1), nothing shifts
    if (this.head === this.data.length) {
      this.data = [];                    // empty again: drop the used slots
      this.head = 0;
    }
    return x;
  }
  front() {
    return this.head === this.data.length ? -1 : this.data[this.head];
  }
  isEmpty() {
    return this.head === this.data.length;
  }
  size() {
    return this.data.length - this.head;
  }
}

