    this.head = 0;              // index of the front item
    this.count = 0;             // how many items are stored
  }
  enqueue(x) {
    if (this.count === this.data.length) this.grow();   // full: double first
    const tail = (this.head + this.count) % this.data.length;
    this.data[tail] = x;        // the slot after the last item, wrapping to 0
    this.count++;
  }
  dequeue() {
    if (this.count === 0) return -1;                     // underflow
    const x = this.data[this.head];
    this.head = (this.head + 1) % this.data.length;      // the front moves on, wrapping
    this.count--;
    return x;
  }
  front() {
    return this.count === 0 ? -1 : this.data[this.head];
  }
  isEmpty() {
    return this.count === 0;
  }
  size() {
    return this.count;
  }
  grow() {
    const bigger = new Array(this.data.length * 2);
    for (let i = 0; i < this.count; i++) {
      bigger[i] = this.data[(this.head + i) % this.data.length];   // unwrap, front first
    }
    this.data = bigger;
    this.head = 0;
  }
}

class ArrayQueue:
    def __init__(self):
        self.data = [0] * 4                  # the slots; the queue wraps around them
        self.head = 0                        # index of the front item
        self.count = 0                       # how many items are stored

    def enqueue(self, x: int) -> None:
        if self.count == len(self.data):
            self._grow()                     # full: double first
        tail = (self.head + self.count) % len(self.data)
        self.data[tail] = x                  # the slot after the last item, wrapping to 0
        self.count += 1

    def dequeue(self) -> int:
        if self.count == 0:
            return -1                        # underflow
        x = self.data[self.head]
        self.head = (self.head + 1) % len(self.data)   # the front moves on, wrapping
        self.count -= 1
        return x

    def front(self) -> int:
        return -1 if self.count == 0 else self.data[self.head]

    def is_empty(self) -> bool:
        return self.count == 0

    def size(self) -> int:
        return self.count

    def _grow(self) -> None:
        cap = len(self.data)
        # unwrap, front first, into twice the room
        self.data = [self.data[(self.head + i) % cap] for i in range(self.count)] + [0] * cap
        self.head = 0

class ArrayQueue {
    private int[] data = new int[4];   // the slots; the queue wraps around them
    private int head = 0;              // index of the front item
    private int count = 0;             // how many items are stored

    void enqueue(int x) {
        if (count == data.length) grow();                  // full: double first
        int tail = (head + count) % data.length;
        data[tail] = x;                // the slot after the last item, wrapping to 0
        count++;
    }

    int dequeue() {
        if (count == 0) return -1;                         // underflow
        int x = data[head];
        head = (head + 1) % data.length;                   // the front moves on, wrapping
        count--;
        return x;
    }

    int front() {
        return count == 0 ? -1 : data[head];
    }

    boolean isEmpty() {
        return count == 0;
    }

    int size() {
        return count;
    }

    private void grow() {
        int[] bigger = new int[data.length * 2];
        for (int i = 0; i < count; i++) {
            bigger[i] = data[(head + i) % data.length];    // unwrap, front first
        }
        data = bigger;
        head = 0;
    }
}

